def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    coords = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    # The seed is the contiguous group of non-background cells in a row or column.
    best = None
    for r, c in coords:
        for dr, dc in ((1, 0), (0, 1)):
            run = []
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg:
                run.append((rr, cc))
                rr += dr
                cc += dc
            if len(run) > (len(best) if best else 0):
                best = run
    # Select the longest straight sequence; isolated markers are not part of it.
    seed = best
    vertical = len(seed) > 1 and seed[0][1] == seed[-1][1]
    pattern = [grid[r][c] for r, c in seed]
    seedset = set(seed)
    marker_color = None
    counts = {}
    for r, c in coords:
        if (r, c) not in seedset:
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    marker_color = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color:
                if vertical:
                    start = r - len(pattern) // 2
                    for i, v in enumerate(pattern):
                        rr = start + i
                        if 0 <= rr < h:
                            out[rr][c] = v
                else:
                    start = c - len(pattern) // 2
                    for i, v in enumerate(pattern):
                        cc = start + i
                        if 0 <= cc < w:
                            out[r][cc] = v
    return out
